// Rapport de conformité TDM (roadmap 6.7) — brancher Email (Resend) +
// Telegram à la suite quand les clés seront disponibles.
// L'audit trail détaillé (décision par fiche) est dans les logs Pino
// (grep '"agent":"compliance"' sur le VPS).
const s = $input.first().json;
const t = s.tdm ?? {};
const rapport = `# TRIPTIC — Conformité TDM (${new Date().toLocaleDateString('fr-FR')})\n\n` +
  `**Fiches web actives : ${t.web_active ?? 0}** · en quarantaine (revue Jules) : ${t.web_pending ?? 0}\n\n` +
  `Sources suivies : ${t.sources_total ?? 0} · opt-out détectés et exclus : ${t.sources_opted_out ?? 0}\n\n` +
  `Rappels : aucune fiche web n'est publiée sans l'agent de conformité ;\n` +
  `les opt-outs sont re-vérifiés à chaque fetch ; audit trail complet dans Pino.\n`;
return [{ json: { rapport, ...t } }];
